import fs from "fs-extra";
import xml2js from "xml2js";
import { glob } from "glob";
function textContent(value) {
    return typeof value === "string" ? value : (value?._ ?? "");
}
/**
 * Parse retry attempts from flaky or rerun elements
 * @param elements - Array of flaky failure/error or rerun failure/error elements
 * @returns Array of JUnitRetryAttempt objects
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function parseRetryAttempts(elements) {
    return elements.map((element) => {
        const message = element.$?.message || "";
        const type = element.$?.type || "";
        const trace = element._ || textContent(element.stackTrace?.[0]);
        const systemOut = textContent(element["system-out"]?.[0]);
        const systemErr = textContent(element["system-err"]?.[0]);
        return {
            message,
            type,
            trace,
            systemOut,
            systemErr,
        };
    });
}
/**
 * Read JUnit report files matching a glob pattern
 * @param globPattern - The glob pattern to match JUnit XML files
 * @returns Promise resolving to an array of all test cases from all matching files
 */
export async function readJUnitReportsFromGlob(globPattern, options = {}) {
    if (options.log)
        console.log("Searching for JUnit reports matching pattern:", globPattern);
    const files = await glob(globPattern);
    if (files.length === 0) {
        if (options.log)
            console.warn("No files found matching the pattern:", globPattern);
        return [];
    }
    if (options.log)
        console.log(`Found ${files.length} JUnit report files`);
    const allTestCasesPromises = files.map((file) => parseJUnitReport(file, options));
    const testCasesArrays = await Promise.all(allTestCasesPromises);
    return testCasesArrays.flat();
}
/**
 * Parse a JUnit XML report file and extract test cases
 * @param filePath - Path to the JUnit XML file
 * @returns Promise resolving to an array of test cases
 */
export async function parseJUnitReport(filePath, options = {}) {
    if (options.log)
        console.log("Reading JUnit report file:", filePath);
    const xml = await fs.readFile(filePath, "utf-8");
    const result = await xml2js.parseStringPromise(xml, {
        explicitChildren: true,
        preserveChildrenOrder: true,
    });
    const testCases = [];
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const parseTestSuite = (suite, suiteName) => {
        if (suite.testcase) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            suite.testcase.forEach((testCase) => {
                const { classname, file, lineno, name, time } = testCase.$;
                const hasFailure = testCase.failure !== undefined;
                const failureTrace = hasFailure
                    ? testCase.failure[0]?._ || ""
                    : undefined;
                const failureMessage = hasFailure
                    ? testCase.failure[0]?.$?.message || ""
                    : undefined;
                const failureType = hasFailure
                    ? testCase.failure[0]?.$?.type || ""
                    : undefined;
                const hasError = testCase.error !== undefined;
                const errorTrace = hasError ? testCase.error[0]?._ || "" : undefined;
                const errorMessage = hasError
                    ? testCase.error[0]?.$?.message || ""
                    : undefined;
                const errorType = hasError
                    ? testCase.error[0]?.$?.type || ""
                    : undefined;
                const skipped = testCase.skipped !== undefined;
                const flakyFailures = testCase.flakyFailure
                    ? parseRetryAttempts(testCase.flakyFailure)
                    : [];
                const flakyErrors = testCase.flakyError
                    ? parseRetryAttempts(testCase.flakyError)
                    : [];
                const rerunFailures = testCase.rerunFailure
                    ? parseRetryAttempts(testCase.rerunFailure)
                    : [];
                const rerunErrors = testCase.rerunError
                    ? parseRetryAttempts(testCase.rerunError)
                    : [];
                const children = testCase.$$ ?? [];
                const flakyAttempts = parseRetryAttempts(children.filter((element) => ["flakyFailure", "flakyError"].includes(element["#name"])));
                const rerunAttempts = parseRetryAttempts(children.filter((element) => ["rerunFailure", "rerunError"].includes(element["#name"])));
                const systemOut = textContent(testCase["system-out"]?.[0]);
                const systemErr = textContent(testCase["system-err"]?.[0]);
                testCases.push({
                    suite: suiteName,
                    classname,
                    name,
                    time,
                    file,
                    lineno,
                    hasFailure,
                    failureTrace,
                    failureMessage,
                    failureType,
                    hasError,
                    errorTrace,
                    errorMessage,
                    errorType,
                    skipped,
                    flakyAttempts,
                    rerunAttempts,
                    flakyFailures: flakyFailures.length > 0 ? flakyFailures : undefined,
                    flakyErrors: flakyErrors.length > 0 ? flakyErrors : undefined,
                    rerunFailures: rerunFailures.length > 0 ? rerunFailures : undefined,
                    rerunErrors: rerunErrors.length > 0 ? rerunErrors : undefined,
                    systemOut: systemOut || undefined,
                    systemErr: systemErr || undefined,
                });
            });
        }
        if (suite.testsuite) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            suite.testsuite.forEach((nestedSuite) => {
                const nestedSuiteName = nestedSuite.$.name || suiteName;
                parseTestSuite(nestedSuite, nestedSuiteName);
            });
        }
    };
    if (result.testsuites?.testsuite) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        result.testsuites.testsuite.forEach((suite) => {
            const suiteName = suite.$.name;
            parseTestSuite(suite, suiteName);
        });
    }
    else if (result.testsuite) {
        const suite = result.testsuite;
        const suiteName = suite.$.name;
        parseTestSuite(suite, suiteName);
    }
    else {
        if (options.log)
            console.warn("No test suites found in the provided file.");
    }
    return testCases;
}
