// src/message-formatter.ts
var resultText = (failedTests) => {
  return failedTests > 0 ? `${failedTests} failed tests` : `Passed`;
};
var duration = (start, stop) => {
  const durationInSeconds = (stop - start) / 1e3;
  return durationInSeconds < 1 ? "<1s" : `${new Date(durationInSeconds * 1e3).toISOString().substr(11, 8)}`;
};
var formatResultsMessage = (ctrf, failOnly = false) => {
  const { summary, environment } = ctrf.results;
  const passedTests = summary.passed;
  const failedTests = summary.failed;
  const skippedTests = summary.skipped;
  const pendingTests = summary.pending;
  const otherTests = summary.other;
  let title = "CTRF Test Results";
  let missingEnvProperties = [];
  let buildInfo = "No build information provided";
  if (environment) {
    const { buildName, buildNumber, buildUrl } = environment;
    if (buildName && buildNumber) {
      buildInfo = buildUrl ? `[${buildName} #${buildNumber}](${buildUrl})` : `${buildName} #${buildNumber}`;
    } else if (buildName || buildNumber) {
      buildInfo = `${buildName || ""} ${buildNumber || ""}`;
    }
    if (!buildName) {
      missingEnvProperties.push("buildName");
    }
    if (!buildNumber) {
      missingEnvProperties.push("buildNumber");
    }
    if (!buildUrl) {
      missingEnvProperties.push("buildUrl");
    }
  } else {
    missingEnvProperties = ["buildName", "buildNumber", "buildUrl"];
  }
  const color = failedTests > 0 ? "FF0000" : "36a64f";
  const testSummary = `&#x2705; ${passedTests} | &#x274C; ${failedTests} | &#x23E9; ${skippedTests} | &#x23F3; ${pendingTests} | &#x2753; ${otherTests}`;
  const jiraIssueUrl = ctrf.results.extra?.jiraIssueUrl;
  const jiraIssueKey = ctrf.results.extra?.jiraIssue;
  const facts = [
    { name: "Test Summary", value: testSummary },
    { name: "Results", value: resultText(failedTests) },
    {
      name: "Duration",
      value: `*Duration:* ${duration(summary.start, summary.stop)}`
    },
    { name: "Build", value: buildInfo }
  ];
  if (jiraIssueUrl) {
    facts.push({
      name: "Jira Issue",
      value: jiraIssueKey ? `[${jiraIssueKey}](${jiraIssueUrl})` : `[View Jira Issue](${jiraIssueUrl})`
    });
  }
  const sections = [
    {
      activityTitle: title,
      facts,
      markdown: true
    }
  ];
  if (missingEnvProperties.length > 0) {
    sections.push({
      activitySubtitle: `&#x26A0; Missing environment properties: ${missingEnvProperties.join(", ")}. Add these to your CTRF report for a better experience.`,
      markdown: true
    });
  }
  sections.push({
    text: "[A CTRF plugin](https://github.com/ctrf-io/teams-ctrf)",
    markdown: true
  });
  return {
    "@type": "MessageCard",
    "@context": "http://schema.org/extensions",
    summary: title,
    themeColor: color,
    sections
  };
};
var formatFlakyTestsMessage = (ctrf) => {
  const { environment, tests } = ctrf.results;
  const flakyTests = tests.filter((test) => test.flaky);
  if (flakyTests.length === 0) {
    return null;
  }
  let title = "Flaky Test Report";
  let missingEnvProperties = [];
  let buildInfo = "No build information provided";
  if (environment) {
    const { buildName, buildNumber, buildUrl } = environment;
    if (buildName && buildNumber) {
      buildInfo = buildUrl ? `[${buildName} #${buildNumber}](${buildUrl})` : `${buildName} #${buildNumber}`;
    } else if (buildName || buildNumber) {
      buildInfo = `${buildName || ""} ${buildNumber || ""}`;
    }
    if (!buildName) {
      missingEnvProperties.push("buildName");
    }
    if (!buildNumber) {
      missingEnvProperties.push("buildNumber");
    }
    if (!buildUrl) {
      missingEnvProperties.push("buildUrl");
    }
  } else {
    missingEnvProperties = ["buildName", "buildNumber", "buildUrl"];
  }
  const flakyTestsText = flakyTests.map((test) => `- ${test.name}`).join("\n");
  const jiraFlakyIssueUrl = ctrf.results.extra?.jiraFlakyIssueUrl;
  const jiraFlakyIssueKey = ctrf.results.extra?.jiraFlakyIssue;
  const flakyFacts = [
    { name: "&#x1F342; Flaky Tests Detected" },
    { name: "Flaky Tests", value: flakyTestsText },
    { name: "Build", value: buildInfo }
  ];
  if (jiraFlakyIssueUrl) {
    flakyFacts.push({
      name: "Jira Issue",
      value: jiraFlakyIssueKey ? `[${jiraFlakyIssueKey}](${jiraFlakyIssueUrl})` : `[View Jira Issue](${jiraFlakyIssueUrl})`
    });
  }
  const sections = [
    {
      activityTitle: title,
      facts: flakyFacts,
      markdown: true
    }
  ];
  if (missingEnvProperties.length > 0) {
    sections.push({
      activitySubtitle: `&#x26A0; Missing environment properties: ${missingEnvProperties.join(", ")}. Add these to your CTRF report for a better experience.`,
      markdown: true
    });
  }
  sections.push({
    text: "[A CTRF plugin](https://github.com/ctrf-io/teams-ctrf)",
    markdown: true
  });
  return {
    "@type": "MessageCard",
    "@context": "http://schema.org/extensions",
    summary: title,
    themeColor: "#FFA500",
    sections
  };
};
var formatAiSummaryForTest = (test, environment) => {
  let title = "AI Test Summary";
  let missingEnvProperties = [];
  if (!test.ai) {
    return null;
  }
  let buildInfo = "No build information provided";
  if (environment) {
    const { buildName, buildNumber, buildUrl } = environment;
    if (buildName && buildNumber) {
      buildInfo = buildUrl ? `[${buildName} #${buildNumber}](${buildUrl})` : `${buildName} #${buildNumber}`;
    } else if (buildName || buildNumber) {
      buildInfo = `${buildName || ""} ${buildNumber || ""}`;
    }
    if (!buildName) {
      missingEnvProperties.push("buildName");
    }
    if (!buildNumber) {
      missingEnvProperties.push("buildNumber");
    }
    if (!buildUrl) {
      missingEnvProperties.push("buildUrl");
    }
  } else {
    missingEnvProperties = ["buildName", "buildNumber", "buildUrl"];
  }
  const sections = [
    {
      activityTitle: title,
      facts: [
        { name: "Test Name", value: test.name },
        { name: "Status", value: "Failed" },
        {
          name: "&#x2728; AI Summary",
          value: test.ai || "No AI summary provided."
        },
        { name: "Build", value: buildInfo }
      ],
      markdown: true
    }
  ];
  if (missingEnvProperties.length > 0) {
    sections.push({
      activitySubtitle: `&#x26A0; Missing environment properties: ${missingEnvProperties.join(", ")}. Add these to your CTRF report for a better experience.`,
      markdown: true
    });
  }
  sections.push({
    text: "[A CTRF plugin](https://github.com/ctrf-io/teams-ctrf)",
    markdown: true
  });
  return {
    "@type": "MessageCard",
    "@context": "http://schema.org/extensions",
    summary: title,
    themeColor: "FF0000",
    sections
  };
};
var formatResultsAdaptiveCard = (ctrf) => {
  const { summary, environment } = ctrf.results;
  const passedTests = summary.passed;
  const failedTests = summary.failed;
  const skippedTests = summary.skipped;
  const pendingTests = summary.pending;
  const otherTests = summary.other;
  let appTitle = "CTRF";
  let buildInfo = null;
  let buildTitle = "Build Info";
  if (environment) {
    const { appName, buildName, buildNumber, buildUrl } = environment;
    if (appName) {
      appTitle = appName;
    }
    if (buildName && buildNumber) {
      buildTitle = `${buildName} #${buildNumber}`;
    } else if (buildName || buildNumber) {
      buildTitle = `${buildName || ""}${buildNumber || ""}`;
    }
    if (buildUrl) {
      buildInfo = buildUrl;
    }
  }
  const jiraIssueUrl = ctrf.results.extra?.jiraIssueUrl;
  const jiraIssueKey = ctrf.results.extra?.jiraIssue;
  const testStatusMapping = {
    passed: { emoji: `\u2705`, chartColor: "good", textColor: "good" },
    failed: { emoji: `\u274C`, chartColor: "attention", textColor: "attention" },
    skipped: { emoji: `\u23E9\uFE0F`, chartColor: "divergingCyan", textColor: "accent" },
    pending: { emoji: `\u231B`, chartColor: "neutral", textColor: "default" },
    other: { emoji: `\u2753\uFE0F`, chartColor: "warning", textColor: "warning" }
  };
  let titleStatus = "passed";
  if (failedTests > 0) {
    titleStatus = "failed";
  }
  return {
    type: "message",
    attachments: [
      {
        contentType: "application/vnd.microsoft.card.adaptive",
        content: {
          $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
          type: "AdaptiveCard",
          version: "1.5",
          speak: `${appTitle} Test Results. ${resultText(failedTests)} in ${duration(summary.start, summary.stop)}`,
          msteams: {
            width: "Full"
          },
          body: [
            {
              type: "Container",
              items: [
                {
                  type: "TextBlock",
                  size: "Large",
                  weight: "Bolder",
                  text: `${testStatusMapping[titleStatus].emoji}  ${appTitle} Test Results`,
                  wrap: true
                }
              ],
              style: testStatusMapping[titleStatus].textColor,
              bleed: true
            },
            {
              type: "ColumnSet",
              columns: [
                {
                  type: "Column",
                  width: "100px",
                  items: [
                    {
                      title: "Summary",
                      data: [
                        {
                          legend: "Passed",
                          color: testStatusMapping["passed"].chartColor,
                          value: passedTests
                        },
                        {
                          legend: "Failed",
                          color: testStatusMapping["failed"].chartColor,
                          value: failedTests
                        },
                        {
                          legend: "Skipped",
                          color: testStatusMapping["skipped"].chartColor,
                          value: skippedTests
                        },
                        {
                          legend: "Pending",
                          color: testStatusMapping["pending"].chartColor,
                          value: pendingTests
                        },
                        {
                          legend: "Other",
                          color: testStatusMapping["other"].chartColor,
                          value: otherTests
                        }
                      ],
                      type: "Chart.Donut"
                    }
                  ]
                },
                {
                  type: "Column",
                  width: "stretch",
                  verticalContentAlignment: "center",
                  items: [
                    {
                      type: "ColumnSet",
                      columns: [
                        {
                          type: "Column",
                          width: "auto",
                          items: [
                            {
                              type: "TextBlock",
                              text: `Summary:`,
                              weight: "Bolder"
                            }
                          ]
                        },
                        {
                          type: "Column",
                          width: "auto",
                          items: [
                            {
                              type: "TextBlock",
                              text: `${testStatusMapping["passed"].emoji} ${String(passedTests)}`,
                              color: testStatusMapping["passed"].textColor,
                              weight: "Bolder",
                              wrap: true
                            }
                          ]
                        },
                        {
                          type: "Column",
                          width: "auto",
                          items: [
                            {
                              type: "TextBlock",
                              text: `${testStatusMapping["failed"].emoji} ${String(failedTests)}`,
                              color: testStatusMapping["failed"].textColor,
                              weight: "Bolder",
                              wrap: true
                            }
                          ]
                        },
                        {
                          type: "Column",
                          width: "auto",
                          items: [
                            {
                              type: "TextBlock",
                              text: `${testStatusMapping["skipped"].emoji} ${String(skippedTests)}`,
                              color: testStatusMapping["skipped"].textColor,
                              weight: "Bolder",
                              wrap: true
                            }
                          ]
                        },
                        {
                          type: "Column",
                          width: "auto",
                          items: [
                            {
                              type: "TextBlock",
                              text: `${testStatusMapping["pending"].emoji} ${String(pendingTests)}`,
                              color: testStatusMapping["pending"].textColor,
                              weight: "Bolder",
                              wrap: true
                            }
                          ]
                        },
                        {
                          type: "Column",
                          width: "auto",
                          items: [
                            {
                              type: "TextBlock",
                              text: `${testStatusMapping["other"].emoji} ${String(otherTests)}`,
                              color: testStatusMapping["other"].textColor,
                              weight: "Bolder",
                              wrap: true
                            }
                          ]
                        }
                      ]
                    },
                    {
                      type: "ColumnSet",
                      columns: [
                        {
                          type: "Column",
                          width: "auto",
                          items: [
                            {
                              type: "TextBlock",
                              text: "Results:",
                              weight: "Bolder",
                              wrap: true
                            }
                          ]
                        },
                        {
                          type: "Column",
                          width: "auto",
                          items: [
                            {
                              type: "TextBlock",
                              text: `${resultText(failedTests)}`,
                              weight: "Bolder",
                              wrap: true
                            }
                          ]
                        }
                      ]
                    },
                    {
                      type: "ColumnSet",
                      columns: [
                        {
                          type: "Column",
                          width: "auto",
                          items: [
                            {
                              type: "TextBlock",
                              text: "Duration:",
                              weight: "Bolder",
                              wrap: true
                            }
                          ]
                        },
                        {
                          type: "Column",
                          width: "auto",
                          items: [
                            {
                              type: "TextBlock",
                              text: `${duration(summary.start, summary.stop)}`,
                              weight: "Bolder",
                              wrap: true
                            }
                          ]
                        }
                      ]
                    }
                  ]
                }
              ]
            }
          ],
          actions: [
            ...buildInfo ? [
              {
                type: "Action.OpenUrl",
                title: buildTitle,
                url: buildInfo
              }
            ] : [],
            ...jiraIssueUrl ? [
              {
                type: "Action.OpenUrl",
                title: jiraIssueKey ? `Jira: ${jiraIssueKey}` : "View Jira Issue",
                url: jiraIssueUrl
              }
            ] : []
          ]
        }
      }
    ]
  };
};

// src/teams-notify.ts
import https from "https";
var sendTeamsMessage = (message) => {
  const teamsWebhookUrl = process.env.TEAMS_WEBHOOK_URL;
  if (!teamsWebhookUrl) {
    return Promise.reject(
      new Error(
        "TEAMS_WEBHOOK_URL is not defined in the environment variables"
      )
    );
  }
  return new Promise((resolve, reject) => {
    const url = new URL(teamsWebhookUrl);
    const data = new TextEncoder().encode(JSON.stringify(message));
    const options = {
      hostname: url.hostname,
      path: url.pathname + url.search,
      method: "POST",
      headers: {
        "Content-Type": "application/json; charset=utf-8",
        "Content-Length": data.length
      }
    };
    const req = https.request(options, (res) => {
      let response = "";
      res.on("data", (chunk) => {
        response += chunk;
      });
      res.on("end", () => {
        if (res.statusCode === 200 || res.statusCode === 202) {
          resolve();
        } else {
          reject(
            new Error(
              `Failed to send message, status code: ${res.statusCode}, response: ${response}, data: ${data}`
            )
          );
        }
      });
    });
    req.on("error", (error) => {
      reject(error);
    });
    req.write(data);
    req.end();
  });
};

// src/teams-reporter.ts
async function sendTestResultsToTeams(report, options = {}, logs = false) {
  if (options.token) {
    process.env.TEAMS_WEBHOOK_URL = options.token;
  }
  if (options.onFailOnly && report.results.summary.failed === 0) {
    logs && console.log("No failed tests. Message not sent.");
    return;
  }
  const message = options.useAdaptiveCard ? formatResultsAdaptiveCard(report) : formatResultsMessage(report);
  await sendTeamsMessage(message);
  logs && console.log("Test results message sent to Teams.");
}
async function sendFlakyResultsToTeams(report, options = {}, logs = false) {
  if (options.token) {
    process.env.TEAMS_WEBHOOK_URL = options.token;
  }
  const message = formatFlakyTestsMessage(report);
  if (message) {
    await sendTeamsMessage(message);
    logs && console.log("Flaky tests message sent to Teams.");
  } else {
    logs && console.log("No flaky tests detected. No message sent.");
  }
}
async function sendAISummaryToTeams(report, options = {}, logs = false) {
  if (options.token) {
    process.env.TEAMS_WEBHOOK_URL = options.token;
  }
  for (const test of report.results.tests) {
    if (test.status === "failed") {
      const message = formatAiSummaryForTest(
        test,
        report.results.environment || {}
      );
      if (message) {
        await sendTeamsMessage(message);
        logs && console.log(`AI summary message sent to Teams for ${test.name}.`);
      }
    }
  }
}
export {
  sendAISummaryToTeams,
  sendFlakyResultsToTeams,
  sendTestResultsToTeams
};
