// src/models/bedrock.ts
async function bedrock(systemPrompt, prompt, args) {
  const region = process.env.AWS_REGION ?? "us-west-2";
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  const sessionToken = process.env.AWS_SESSION_TOKEN;
  if (accessKeyId == null || secretAccessKey == null) {
    console.error(
      "AWS credentials not found. Please set AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY environment variables."
    );
    return null;
  }
  try {
    const { BedrockRuntimeClient, InvokeModelCommand } = await import("@aws-sdk/client-bedrock-runtime");
    const client = new BedrockRuntimeClient({
      region,
      credentials: {
        accessKeyId,
        secretAccessKey,
        ...sessionToken != null && { sessionToken }
      }
    });
    const modelId = args.model ?? "anthropic.claude-3-5-sonnet-20240620-v1:0";
    const body = JSON.stringify({
      anthropic_version: "bedrock-2023-05-31",
      max_tokens: args.maxTokens ?? 4e3,
      system: systemPrompt,
      messages: [
        {
          role: "user",
          content: stripAnsi(prompt)
        }
      ],
      ...args.temperature != null && { temperature: args.temperature },
      ...args.topP != null && { top_p: args.topP }
    });
    const command = new InvokeModelCommand({
      modelId,
      body,
      contentType: "application/json",
      accept: "application/json"
    });
    const response = await client.send(command);
    const responseBody = JSON.parse(new TextDecoder().decode(response.body));
    if (responseBody.content?.[0]?.text != null) {
      return responseBody.content[0].text;
    }
    return null;
  } catch (error) {
    console.error("Error invoking Bedrock:", error);
    return null;
  }
}
