// src/models/openai.ts
async function openAI(systemPrompt, prompt, args) {
  const client = new OpenAI6({
    apiKey: process.env.OPENAI_API_KEY
  });
  try {
    const response = await client.chat.completions.create({
      model: args.model ?? "gpt-4o",
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: stripAnsi(prompt) }
      ],
      max_tokens: args.maxTokens ?? null,
      frequency_penalty: args.frequencyPenalty,
      presence_penalty: args.presencePenalty,
      ...args.temperature !== void 0 ? { temperature: args.temperature } : {},
      ...args.topP !== void 0 ? { top_p: args.topP } : {}
    });
    return response.choices[0].message?.content ?? null;
  } catch (error) {
    console.error(`Error invoking OpenAI`, error);
    return null;
  }
}
